# Lab 12 - a radio link for sensor readings (BEFORE hardening). Flash the SAME
# main.py on both boards. Press A: send the next reading. Every frame carries a
# sequence number and a CRC-16, so corrupted frames are rejected - but nothing
# notices a LOST frame: it works on a quiet bench and silently drops data in a
# noisy room. The build task adds acks, retransmit and duplicate suppression.
from microbit import *
import radio

GROUP = 12
radio.config(group=GROUP)       # default length=32 bytes, queue=3 frames


def crc16(text):
    # CRC-16/CCITT-FALSE (poly 0x1021, init 0xFFFF): catches flipped bits
    crc = 0xFFFF
    for ch in text:
        crc ^= ord(ch) << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x1021) if crc & 0x8000 else (crc << 1)
            crc &= 0xFFFF
    return crc


def encode(kind, seq, payload):
    body = "{}:{}:{}".format(kind, seq, payload)    # kind D = data, A = ack
    return "{}:{:04X}".format(body, crc16(body))    # checksum over the whole body


def decode(text):
    # returns (kind, seq, payload) or None; nothing from the air is trusted
    body, sep, check = text.rpartition(":")
    if not sep or len(check) != 4:
        return None
    try:
        if int(check, 16) != crc16(body):
            return None
        kind, seq, payload = body.split(":", 2)
        return kind, int(seq), payload
    except ValueError:
        return None


def new_state():
    return {"seq": 0, "delivered": [],
            "stats": {"tx": 0, "rx": 0, "bad": 0, "delivered": 0}}


def jline(t, stats):
    # observability: one JSON line per report, keys in a fixed order
    keys = ("tx", "rx", "bad", "delivered")
    return '{"t":%d,' % t + ",".join('"%s":%d' % (k, stats[k]) for k in keys) + "}"


def send(state, payload):
    state["seq"] += 1
    radio.send(encode("D", state["seq"], payload))  # fire and forget
    state["stats"]["tx"] += 1


def deliver(state, seq, payload):
    state["delivered"].append(payload)
    state["stats"]["delivered"] += 1
    print("rx", seq, payload)


def receive(state):
    while True:                         # drain the queue: it holds only 3 frames
        try:
            text = radio.receive()
        except ValueError:              # not a radio.send() string
            text = "?"
        if text is None:
            return
        state["stats"]["rx"] += 1
        msg = decode(text)
        if msg is None:
            state["stats"]["bad"] += 1  # wrong CRC or format: drop it
        elif msg[0] == "D":
            deliver(state, msg[1], msg[2])


def step(state):
    if button_a.was_pressed():
        send(state, temperature())
    receive(state)


def main():
    print("link group", GROUP)
    state = new_state()
    while True:
        step(state)
        if button_b.was_pressed():
            print(jline(running_time(), state["stats"]))
        sleep(10)


if __name__ == "__main__":
    main()

// Lab 16 - a timer interrupt and the main loop share a counter (BEFORE: racy).
// Target: nRF52833 (micro:bit V2), Rust + Embassy. Runs under Renode's nRF52840
// model as a CLOSE SIBLING (same TIMER1/UART0 addresses and IRQ numbers; NOT
// the micro:bit board) - see ../README.md "What differs from real V2 hardware".
//
// TIMER1 fires every 100 us and adds 1 to PENDING. The main loop "takes" the
// pending ticks: read PENDING, do some work, write 0. If the interrupt fires
// between the read and the write, its tick is wiped out: a lost update.
// AtomicU32 does not help - two separate atomic operations are not one.
#![no_std]
#![no_main]

use core::fmt::Write;
use core::sync::atomic::{AtomicU32, Ordering::Relaxed};
use embassy_executor::Spawner;
use embassy_nrf::interrupt;
use embassy_nrf::interrupt::{InterruptExt, Priority};
use embassy_time::Timer;
use panic_halt as _;

// nRF52833 Product Specification: TIMER1 base 0x40009000, UART0 base 0x40002000
const TIMER1_BASE: usize = 0x4000_9000;
const UART0_BASE: usize = 0x4000_2000;

fn reg_write(base: usize, offset: usize, value: u32) {
    unsafe { core::ptr::write_volatile((base + offset) as *mut u32, value) }
}

fn reg_read(base: usize, offset: usize) -> u32 {
    unsafe { core::ptr::read_volatile((base + offset) as *const u32) }
}

static PENDING: AtomicU32 = AtomicU32::new(0); // shared: ISR adds, main takes
static ISR_TOTAL: AtomicU32 = AtomicU32::new(0); // written only by the ISR

#[interrupt]
unsafe fn TIMER1() {
    reg_write(TIMER1_BASE, 0x140, 0); // EVENTS_COMPARE[0] = 0, or the IRQ fires again at once
    PENDING.store(PENDING.load(Relaxed) + 1, Relaxed); // safe here: main cannot preempt an ISR
    ISR_TOTAL.fetch_add(1, Relaxed);
}

// RACE: read ... window ... write. A tick added inside the window is lost.
fn take() -> u32 {
    let n = PENDING.load(Relaxed);
    cortex_m::asm::delay(2_000); // "work" between read and write widens the window
    PENDING.store(0, Relaxed);
    n
}

fn start_timer1() {
    reg_write(TIMER1_BASE, 0x504, 0); // MODE = Timer
    reg_write(TIMER1_BASE, 0x508, 3); // BITMODE = 32 bit
    reg_write(TIMER1_BASE, 0x510, 4); // PRESCALER = 4: 16 MHz / 2^4 = 1 MHz
    reg_write(TIMER1_BASE, 0x540, 100); // CC[0] = 100 ticks = 100 us
    reg_write(TIMER1_BASE, 0x200, 1); // SHORTS: COMPARE0 -> CLEAR (periodic)
    reg_write(TIMER1_BASE, 0x304, 1 << 16); // INTENSET: COMPARE[0]
    interrupt::TIMER1.set_priority(Priority::P2);
    unsafe { interrupt::TIMER1.enable() };
    reg_write(TIMER1_BASE, 0x00C, 1); // TASKS_CLEAR
    reg_write(TIMER1_BASE, 0x000, 1); // TASKS_START
}

// Legacy UART0 TX on P0.06 (micro:bit V2: target TX to the interface MCU), 115200 baud.
struct Uart;

impl Uart {
    fn init() -> Self {
        reg_write(UART0_BASE, 0x50C, 6); // PSEL.TXD = P0.06, connected
        reg_write(UART0_BASE, 0x524, 0x01D7_E000); // BAUDRATE = 115200
        reg_write(UART0_BASE, 0x500, 4); // ENABLE = UART
        reg_write(UART0_BASE, 0x008, 1); // TASKS_STARTTX
        Uart
    }
}

impl Write for Uart {
    fn write_str(&mut self, s: &str) -> core::fmt::Result {
        for b in s.bytes() {
            reg_write(UART0_BASE, 0x11C, 0); // clear EVENTS_TXDRDY
            reg_write(UART0_BASE, 0x51C, b as u32); // TXD
            while reg_read(UART0_BASE, 0x11C) == 0 {}
        }
        Ok(())
    }
}

#[embassy_executor::main]
async fn main(_spawner: Spawner) {
    let _p = embassy_nrf::init(Default::default()); // clocks + RTC1 time driver
    let mut uart = Uart::init();
    start_timer1();
    let mut consumed: u32 = 0;
    let mut lost_total: u32 = 0;
    for round in 1..=20u32 {
        for _ in 0..50 {
            consumed += take();
            Timer::after_micros(500).await;
        }
        // observability: a consistent snapshot (interrupts masked while we read both)
        let (isr, pending) = critical_section::with(|_| (ISR_TOTAL.load(Relaxed), PENDING.load(Relaxed)));
        let lost = isr - consumed - pending; // invariant: isr == consumed + pending + lost
        lost_total = lost;
        let _ = write!(uart, "round={} isr={} consumed={} pending={} lost={}\r\n", round, isr, consumed, pending, lost);
    }
    let _ = write!(uart, "done lost_total={}\r\n", lost_total);
    loop {
        Timer::after_secs(1).await;
    }
}
